  tip_5: 'வகுப்புச் செயல்பாடு: ஒவ்வொரு மாணவரின் உயரத்தையும் எழுதி, "தொகுப்பு அட்டவணை உருவாக்கு" அழுத்தி, இரண்டு ஓஜைவ்களையும் பாருங்கள். அவை இடைநிலை அளவில் சந்திக்கின்றனவா?',
  tip_6: 'அச்சிட்டால் எல்லா அட்டவணைகளுடனும் தெளிவான தீர்வு கிடைக்கும். ஸ்மார்ட்போர்டில் படிகளை விளக்க முழுத் திரையைப் பயன்படுத்துங்கள்.',
