  decimals: 'தசம இடங்கள்',
  incl_note: 'இவை உள்ளடக்கிய பிரிவுகள். தொடர்ச்சியாக்க ஒவ்வொரு கீழ் எல்லையிலிருந்தும் {g} கழிக்கப்பட்டு ஒவ்வொரு மேல் எல்லையுடனும் கூட்டப்பட்டது; எனவே {a} இப்போது {b}.',
  dup_note: 'சில மதிப்புகள் ஒன்றுக்கு மேற்பட்ட வரிசைகளில் உள்ளன, எனவே அவற்றின் நிகழ்வெண்கள் கூட்டப்பட்டன.',
  unequal_note: 'எல்லாப் பிரிவுகளின் அகலமும் சமமில்லை. NCERT 9-ஆம் வகுப்பில் உள்ளபடி, செவ்வக வரைபடம் சரிசெய்த நிகழ்வெண் = f × (மிகச் சிறிய அகலம் ÷ பிரிவு அகலம்) பயன்படுத்துகிறது.',
  err_empty: 'தொடங்க சில எண்களைத் தட்டச்சு செய்யுங்கள் அல்லது ஒட்டுங்கள்.',
  err_empty_t: 'அட்டவணையின் குறைந்தது ஒரு வரிசையை நிரப்புங்கள்.',
  err_total0: 'மொத்த நிகழ்வெண் 0. குறைந்தது ஒரு நிகழ்வெண்ணை எழுதுங்கள்.',
  err_row: 'வரிசை {r}: ஒவ்வொரு கட்டத்திலும் ஒரு எண் எழுதுங்கள்.',
  err_negf: 'வரிசை {r}: நிகழ்வெண் குறை எண்ணாக இருக்கக் கூடாது.',
  err_fint: 'வரிசை {r}: நிகழ்வெண் முழு எண்ணாக இருக்க வேண்டும் (0, 1, 2, …).',
  err_limits: 'வரிசை {r}: மேல் எல்லை கீழ் எல்லையை விடப் பெரியதாக இருக்க வேண்டும்.',
  err_overlap: '{a}, {b} ஆகிய பிரிவுகள் ஒன்றின் மேல் ஒன்று விழுகின்றன. முந்தைய பிரிவு முடியும் இடத்திலேயே அடுத்த பிரிவு தொடங்க வேண்டும்.',
  err_gap: '{a} பிரிவுக்குப் பிறகு இடைவெளி உள்ளது. பிரிவுகளைத் தொடர்ச்சியாக்குங்கள் (எ.கா. 10–20, 20–30).',
  err_toomany: 'நிறைய எண்கள்! முதல் {n} எண்கள் மட்டுமே எடுக்கப்பட்டன.',
  err_toomanyrows: 'ஓர் அட்டவணையில் அதிகபட்சம் {n} வரிசைகள் இருக்கலாம்.',
  err_group: '0-ஐ விடப் பெரிய பிரிவு அகலத்தைத் தேர்ந்தெடுங்கள்; தொடக்கம் மிகச் சிறிய எண்ணை விடப் பெரியதாக இருக்கக் கூடாது.',
  err_quick: 'தொடக்கம், 0-ஐ விடப் பெரிய அகலம், 1 முதல் {n} வரை பிரிவுகளின் எண்ணிக்கை ஆகியவற்றை எழுதுங்கள்.',
  err_calc: 'இந்தக் கணக்கில் ஏதோ தவறு நடந்தது. தரவைச் சரிபாருங்கள்.',
  need_data: 'தீர்வைக் காண மேலே உங்கள் தரவை எழுதுங்கள்.',
  confirm_clear: 'இந்த அட்டவணையின் எல்லா வரிசைகளையும் அழிக்கவா?',
