  chart_label: 'உங்கள் தரவின் வரைபடம்',
  hist_note: 'பிரிவுகள் தொடர்ச்சியானவை, எனவே செவ்வகங்கள் ஒன்றையொன்று தொட்டு நிற்கின்றன. ஒவ்வொரு செவ்வகத்தின் உயரமும் அதன் நிகழ்வெண்.',
  hist_adj_note: 'பிரிவுகளின் அகலங்கள் வேறுபடுகின்றன, எனவே உயரம் சரிசெய்த நிகழ்வெண்ணைக் காட்டுகிறது; ஒவ்வொரு செவ்வகத்தின் பரப்பும் அதன் நிகழ்வெண்ணுக்கு ஏற்ப உள்ளது.',
  bar_note: 'ஒவ்வொரு பட்டையின் உயரமும் அந்த மதிப்பு எத்தனை முறை வருகிறது என்பதைக் காட்டுகிறது.',
  poly_note: 'செவ்வகங்களின் மேல் பக்கங்களின் நடுப்புள்ளிகளை இணையுங்கள். பலகோணம் x-அச்சைத் தொட இரு முனைகளிலும் ஒரு வெற்றுப் பிரிவு சேர்க்கப்பட்டுள்ளது.',
  poly_note_d: 'ஒவ்வொரு புள்ளியையும் (x, f) குறித்து, புள்ளிகளை நேர்கோடுகளால் இணையுங்கள்.',
  ogive_meet: 'குவிவு நிகழ்வெண் n ÷ 2 = {y} ஆக இருக்கும் இடத்தில், அதாவது x = {x}-இல், இரண்டு ஓஜைவ்களும் சந்திக்கின்றன. இதுவே இடைநிலை அளவு.',
  ogive_meet_d: 'இரண்டு வளைவுகளும் ஏறக்குறைய x = {x}-இல் வெட்டுகின்றன. தரவின் இடைநிலை அளவு {m}.',
  auto_grp_note: 'இந்த வரைபடத்துக்காக எண்கள் {h} அகலமுள்ள பிரிவுகளாகத் தொகுக்கப்பட்டுள்ளன.',
