  th_dev: 'விலக்கம்',
  th_tally: 'நேர்க்கோட்டுக் குறிகள்',
  rows_more: 'மொத்தம் {n} வரிசைகளில் முதல் {k} காட்டப்படுகின்றன. கூட்டுத்தொகைகள் எல்லா வரிசைகளையும் உள்ளடக்கும்.',
  mean_raw_1: 'எல்லா மதிப்புகளையும் கூட்டி, கூடுதலை மதிப்புகளின் எண்ணிக்கை n = {n}-ஆல் வகுங்கள்.',
  mean_disc_1: 'ஒவ்வொரு மதிப்பு x-ஐயும் அதன் நிகழ்வெண் f-ஆல் பெருக்கி, பெருக்கல்களைக் கூட்டி, மொத்த நிகழ்வெண் Σf-ஆல் வகுங்கள்.',
  mean_grp_x: 'ஒவ்வொரு பிரிவும் அதன் நடு மதிப்பால் குறிக்கப்படுகிறது: x = (கீழ் எல்லை + மேல் எல்லை) ÷ 2.',
  mean_direct_1: 'ஒவ்வொரு நடு மதிப்பு x-ஐயும் அதன் நிகழ்வெண் f-ஆல் பெருக்கி, எல்லா fx-ஐயும் கூட்டி, Σf-ஆல் வகுங்கள்.',
  mean_assumed_1: 'ஊகச் சராசரி a = {a} என எடுங்கள். ஒவ்வொரு விலக்கம் d = x − a கண்டு, பின் f-ஆல் பெருக்குங்கள்.',
  mean_step_1: 'a = {a}, h = {h} என எடுங்கள். u = (x − a) ÷ h காணுங்கள். இவை சிறிய, எளிய எண்கள்.',
  same_mean: 'மூன்று முறைகளும் ஒரே சராசரியைத் தருகின்றன. எண்கள் எளிதாக இருக்கும் முறையைப் பயன்படுத்துங்கள்.',
  med_sorted: 'மதிப்புகளை ஏறுவரிசையில் அமையுங்கள் (ஒவ்வொரு மதிப்பின் மேலுள்ள சிறிய எண் அதன் இடம்):',
  med_odd: 'n = {n} ஒற்றை எண், எனவே இடைநிலை அளவு ((n + 1) ÷ 2)-ஆவது மதிப்பு, அதாவது {p}-ஆவது மதிப்பு.',
