  err_negf: 'వరుస {r}: పౌనఃపున్యం రుణాత్మకం కాకూడదు.',
  err_fint: 'వరుస {r}: పౌనఃపున్యం పూర్ణ సంఖ్య కావాలి (0, 1, 2, …).',
  err_limits: 'వరుస {r}: ఎగువ హద్దు దిగువ హద్దు కంటే పెద్దదిగా ఉండాలి.',
  err_overlap: '{a}, {b} తరగతులు ఒకదానిపై ఒకటి పడుతున్నాయి. ముందటి తరగతి ఎక్కడ ముగుస్తుందో అక్కడే తర్వాతి తరగతి మొదలవ్వాలి.',
  err_gap: '{a} తరగతి తర్వాత ఖాళీ ఉంది. తరగతులను అవిచ్ఛిన్నంగా చేయండి (ఉదా. 10–20, 20–30).',
  err_toomany: 'చాలా సంఖ్యలు! మొదటి {n} మాత్రమే తీసుకున్నాం.',
  err_toomanyrows: 'ఒక పట్టికలో గరిష్ఠంగా {n} వరుసలు ఉండవచ్చు.',
  err_group: '0 కంటే పెద్ద తరగతి వెడల్పు ఎంచుకోండి; ప్రారంభం అతి చిన్న సంఖ్య కంటే పెద్దది కాకూడదు.',
  err_quick: 'ప్రారంభం, 0 కంటే పెద్ద వెడల్పు, 1 నుండి {n} లోపు తరగతుల సంఖ్య రాయండి.',
  err_calc: 'ఈ లెక్కలో ఏదో పొరపాటు జరిగింది. దయచేసి దత్తాంశం సరిచూడండి.',
