  mean_step_1: 'a = {a}, h = {h} తీసుకోండి. u = (x − a) ÷ h కనుగొనండి. ఇవి చిన్న, సులభమైన సంఖ్యలు.',
  same_mean: 'మూడు పద్ధతులూ ఒకే అంకమధ్యమాన్ని ఇస్తాయి. సంఖ్యలు సులభంగా ఉండే పద్ధతిని వాడండి.',
  med_sorted: 'విలువలను ఆరోహణ క్రమంలో అమర్చండి (ప్రతి విలువ పైన ఉన్న చిన్న సంఖ్య దాని స్థానం):',
  med_odd: 'n = {n} బేసి సంఖ్య, కాబట్టి మధ్యగతం ((n + 1) ÷ 2) వ విలువ, అంటే {p} వ విలువ.',
