  mode_many: 'ఒకటి కంటే ఎక్కువ విలువలు అత్యధిక సార్లు (ఒక్కొక్కటి {f} సార్లు) వచ్చాయి, కాబట్టి దత్తాంశానికి ఒకటి కంటే ఎక్కువ బాహుళకాలు ఉన్నాయి.',
