  sym_f0: 'బాహుళక తరగతికి ముందున్న తరగతి పౌనఃపున్యం',
  sym_f2: 'బాహుళక తరగతి తర్వాతి తరగతి పౌనఃపున్యం',
  mode_tie: 'ఒకటి కంటే ఎక్కువ తరగతులకు అత్యధిక పౌనఃపున్యం ఉంది. ఇక్కడ మొదటిదాన్ని తీసుకున్నాం, కానీ దత్తాంశానికి ఒకటి కంటే ఎక్కువ బాహుళకాలు ఉండవచ్చు.',
  mode_den0: 'ఇక్కడ 2f₁ − f₀ − f₂ = 0, కాబట్టి ఈ సూత్రం బాహుళకాన్ని ఇవ్వదు.',
  empirical: 'అనుభావిక సంబంధం 3 × మధ్యగతం = బాహుళకం + 2 × అంకమధ్యమం తో సరిచూడండి: బాహుళకం ≈ 3 × మధ్యగతం − 2 × అంకమధ్యమం = {v}.',
  q_pos: 'Q₁ అంటే (n + 1) ÷ 4 = {p} స్థానంలోని విలువ. Q₃ అంటే 3(n + 1) ÷ 4 = {q} స్థానంలోని విలువ.',
  q_between: '{p} స్థానం {a} వ విలువ ({va}) కు, {b} వ విలువ ({vb}) కు మధ్య ఉంది. వాటి మధ్య దశాంశ భాగం అంత ముందుకు వెళ్ళండి:',
